import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"D2.1 · 只读连接器与来源视图","description":"Hearth D2.1 开发增量：用户可以连接一个真实邮箱、日历或文档账户，让 Hearth 读取指定范围，并在任务卡上看到来源、时间和原始引用。","frontmatter":{"title":"D2.1 · 只读连接器与来源视图","description":"Hearth D2.1 开发增量：用户可以连接一个真实邮箱、日历或文档账户，让 Hearth 读取指定范围，并在任务卡上看到来源、时间和原始引用。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-2/d2-1.md","filePath":"delivery/stage-2/d2-1.md","lastUpdated":1793761874000}'),l={name:"delivery/stage-2/d2-1.md"};function o(s,a,d,h,n,c){return t(),i("div",null,[...a[0]||(a[0]=[r(`<p class="eyebrow">STAGE 2 · D2.1 · 1 / 6</p><h1 id="d2-1-·-只读连接器与来源视图" tabindex="-1">D2.1 · 只读连接器与来源视图 <a class="header-anchor" href="#d2-1-·-只读连接器与来源视图" aria-label="Permalink to &quot;D2.1 · 只读连接器与来源视图&quot;">​</a></h1><p class="lead">先用一个真实连接器证明权限、来源和撤销边界，再讨论写入与多渠道。</p><p class="page-meta">STAGE 2 · D2.1 · 1 个纵向切片 · 4 个工作包</p><div class="section-grid"><div><strong>用户可见结果</strong>用户可以连接一个真实邮箱、日历或文档账户，让 Hearth 读取指定范围，并在任务卡上看到来源、时间和原始引用。</div><div><strong>完成门槛</strong>只读同步可用；用户能撤销连接；任务只引用被授权范围；来源可追溯到原始对象；UI 不暴露原始凭据。</div></div><h2 id="这一步要交付什么" tabindex="-1">这一步要交付什么 <a class="header-anchor" href="#这一步要交付什么" aria-label="Permalink to &quot;这一步要交付什么&quot;">​</a></h2><p>用户可以连接一个真实邮箱、日历或文档账户，让 Hearth 读取指定范围，并在任务卡上看到来源、时间和原始引用。</p><p>Stage 2 从只读能力逐步走向真实写入。每增加一种权限，都先证明来源、撤销、审批和回执仍然成立。</p><h2 id="开始前" tabindex="-1">开始前 <a class="header-anchor" href="#开始前" aria-label="Permalink to &quot;开始前&quot;">​</a></h2><ul><li>Stage 1 的本地 MVP、两个任务族、审批、幂等、回执和恢复路径稳定。</li><li>已限定首位用户的真实邮箱、日历、文档或数据账户，并准备测试账户。</li><li>连接器只能申请最小范围；任何写入都必须有预览、审批和回执。</li></ul><h2 id="四个实施工作包" tabindex="-1">四个实施工作包 <a class="header-anchor" href="#四个实施工作包" aria-label="Permalink to &quot;四个实施工作包&quot;">​</a></h2><blockquote><p>每个工作包都要产生可运行的代码、可复现的验证或明确的界面结果；只写接口或只做页面都不算完成。</p></blockquote><h3 id="_01-·-连接器授权与凭据托管" tabindex="-1">01 · 连接器授权与凭据托管 <a class="header-anchor" href="#_01-·-连接器授权与凭据托管" aria-label="Permalink to &quot;01 · 连接器授权与凭据托管&quot;">​</a></h3><p>只接入一个真实来源，使用 OAuth PKCE、最小 scope 和短期访问凭据；刷新令牌进入本机秘密存储，不进入日志、任务上下文或模型提示。把客户端、账户、授权范围、过期时间和撤销状态记录成可审计配置。</p><h3 id="_02-·-来源归一化与增量同步" tabindex="-1">02 · 来源归一化与增量同步 <a class="header-anchor" href="#_02-·-来源归一化与增量同步" aria-label="Permalink to &quot;02 · 来源归一化与增量同步&quot;">​</a></h3><p>把邮件、日历或文档对象转换为统一的 SourceRef，保存外部对象 ID、账户、获取时间、范围、内容哈希和原始链接。同步使用游标、去重键、限流和退避；首次全量之后只拉取增量，断线后从最后一个成功游标继续。</p><h3 id="_03-·-来源视图与引用证据" tabindex="-1">03 · 来源视图与引用证据 <a class="header-anchor" href="#_03-·-来源视图与引用证据" aria-label="Permalink to &quot;03 · 来源视图与引用证据&quot;">​</a></h3><p>任务卡只显示本次实际使用的最小来源摘要；来源页展示账户、标题、时间、引用段落、原始对象入口和敏感字段脱敏结果。产物中的每条引用必须能回到 SourceRef，不能用模型生成的伪链接冒充来源。</p><h3 id="_04-·-撤销、隔离与只读验收" tabindex="-1">04 · 撤销、隔离与只读验收 <a class="header-anchor" href="#_04-·-撤销、隔离与只读验收" aria-label="Permalink to &quot;04 · 撤销、隔离与只读验收&quot;">​</a></h3><p>断开连接时立即吊销凭据、停止同步，并使后续任务无法再读取该来源；缓存和索引按策略清理。验收必须覆盖跨账户隔离、过期重连、范围外对象拒绝和真实脱敏任务，全程不暴露原始令牌。</p><h2 id="工程落点" tabindex="-1">工程落点 <a class="header-anchor" href="#工程落点" aria-label="Permalink to &quot;工程落点&quot;">​</a></h2><h3 id="主要目录与模块" tabindex="-1">主要目录与模块 <a class="header-anchor" href="#主要目录与模块" aria-label="Permalink to &quot;主要目录与模块&quot;">​</a></h3><ul><li><code>apps/hearthd/connectors</code> — OAuth、游标同步、来源归一化与撤销</li><li><code>packages/connectors</code> — 邮件、日历、文档和数据的最小权限适配器</li><li><code>packages/executors/python-sidecar</code> — 解析、OCR、表格清洗与格式转换</li><li><code>packages/executors/browser</code> — Playwright worker、下载验证与人工接管</li><li><code>packages/context</code> — Context Compiler、来源裁剪与敏感字段过滤</li><li><code>packages/memory</code> — Memory v0、召回原因与基础遗忘</li><li><code>packages/governor</code> — Token 预算、阶梯路由、缓存与异常停止</li></ul><h3 id="关键接口" tabindex="-1">关键接口 <a class="header-anchor" href="#关键接口" aria-label="Permalink to &quot;关键接口&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接口</th><th>必须保持的契约</th></tr></thead><tbody><tr><td><code>SourceRef</code></td><td>sourceId、connectorId、accountId、objectId、retrievedAt、scope、contentHash、revocationState；引用必须能回到原始对象。</td></tr><tr><td><code>ConnectorEffect</code></td><td>effectType、target、parameters、dryRun、approvalId、idempotencyKey；连接器只执行已登记动作。</td></tr><tr><td><code>ContextPack</code></td><td>taskId、selectedSources、tokenBudget、redactions、recallReasons；不得包含未授权账户内容。</td></tr><tr><td><code>MemoryRecord</code></td><td>kind、value、provenance、confidence、sensitivity、observedAt、expiresAt；纠正与删除必须可追踪。</td></tr></tbody></table><h3 id="共享验证命令" tabindex="-1">共享验证命令 <a class="header-anchor" href="#共享验证命令" aria-label="Permalink to &quot;共享验证命令&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:connectors：授权、过期、撤销、限流和跨账户隔离</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:effects：预览、参数绑定、幂等、outbox</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 重投与对账</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:browser：注入、下载、超时、接管和网络出口策略</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> eval:operator：研究与日常任务对比人工分钟、Token</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 和成功率</span></span></code></pre></div><h2 id="验收演练" tabindex="-1">验收演练 <a class="header-anchor" href="#验收演练" aria-label="Permalink to &quot;验收演练&quot;">​</a></h2><ol><li>从干净的数据目录启动 hearthd，打开 <a href="/hearth-os/delivery/stage-2/d2-1.html">D2.1 页面</a>，确认当前页面没有依赖浏览器缓存或手工种子数据。</li><li>按顺序完成四个工作包：连接器授权与凭据托管、来源归一化与增量同步、来源视图与引用证据、撤销、隔离与只读验收。每完成一个工作包，保存对应测试输出、截图或产物版本。</li><li>复现失败案例“连接器过期或被撤销”。页面必须显示“任务显示重连要求，保留草稿和已完成步骤。”，然后按“重新授权后继续，不重放已成功的外部动作。”恢复；不得出现重复副作用或未登记状态。</li><li>重启服务并重新打开任务，确认运行状态、审批、产物和恢复入口都来自持久投影，而不是只存在于当前页面。</li><li>运行上方的共享验证命令并导出证据。完成门槛是：只读同步可用；用户能撤销连接；任务只引用被授权范围；来源可追溯到原始对象；UI 不暴露原始凭据。</li></ol><h2 id="交付物" tabindex="-1">交付物 <a class="header-anchor" href="#交付物" aria-label="Permalink to &quot;交付物&quot;">​</a></h2><ul><li>一个真实只读连接器</li><li>来源投影与来源详情页</li><li>OAuth scope 清单</li><li>撤销与过期路径演示</li></ul><h2 id="完成判定" tabindex="-1">完成判定 <a class="header-anchor" href="#完成判定" aria-label="Permalink to &quot;完成判定&quot;">​</a></h2><ul><li>[ ] 只读同步可用；用户能撤销连接；任务只引用被授权范围；来源可追溯到原始对象；UI 不暴露原始凭据。</li><li>[ ] 交付物已经和契约、任务卡投影保持一致，没有未登记的字段或状态。</li><li>[ ] 至少一个失败路径有可操作恢复，关键动作留下审计事件。</li><li>[ ] 演示不依赖手工修改数据库、只在终端拼接命令，或永久 mock。</li></ul><h2 id="失败与恢复" tabindex="-1">失败与恢复 <a class="header-anchor" href="#失败与恢复" aria-label="Permalink to &quot;失败与恢复&quot;">​</a></h2><table tabindex="0"><thead><tr><th>情况</th><th>用户看到</th><th>恢复动作</th></tr></thead><tbody><tr><td>连接器过期或被撤销</td><td>任务显示重连要求，保留草稿和已完成步骤。</td><td>重新授权后继续，不重放已成功的外部动作。</td></tr><tr><td>网页内容试图扩大权限</td><td>任务暂停并提示内容不可信，要求用户确认。</td><td>丢弃注入指令，保留来源证据并重新生成安全计划。</td></tr><tr><td>写入结果未知</td><td>显示“等待对账”，不显示成功或允许盲目重试。</td><td>查询测试账户或外部系统，确认后补写回执或执行补偿。</td></tr></tbody></table><h2 id="本增量不包含" tabindex="-1">本增量不包含 <a class="header-anchor" href="#本增量不包含" aria-label="Permalink to &quot;本增量不包含&quot;">​</a></h2><ul><li>不在一个连接器上证明权限、幂等和回执之前扩展多个渠道。</li><li>不自动执行高风险提交、公开发布或不可逆分享。</li><li>不让网页内容、附件或模型输出直接改变权限。</li></ul><h2 id="来源与下一步" tabindex="-1">来源与下一步 <a class="header-anchor" href="#来源与下一步" aria-label="Permalink to &quot;来源与下一步&quot;">​</a></h2><h3 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h3><ul><li><a href="/hearth-os/architecture/gateway.html">个人网关</a></li><li><a href="/hearth-os/architecture/executor-catalog.html">执行器目录</a></li><li><a href="/hearth-os/architecture/security-privacy.html">安全与隐私</a></li><li><a href="/hearth-os/architecture/token-economics.html">Token 经济</a></li></ul><h3 id="完成后的下一步" tabindex="-1">完成后的下一步 <a class="header-anchor" href="#完成后的下一步" aria-label="Permalink to &quot;完成后的下一步&quot;">​</a></h3><p>继续 <a href="/hearth-os/delivery/stage-2/d2-2.html">D2.2 · Document/Data Executor</a>。先完成本增量验收，不要用后续工作掩盖当前缺口。</p>`,42)])])}const k=e(l,[["render",o]]);export{u as __pageData,k as default};
